import { toast } from 'react-toastify';

export default function RemoveButton({ item, onAdd }) {
  function onSelect() {
    toast.error( {
      data: {
        title: 'Oh Snap!',
        content: 'Something went wrong',
      },
      ariaLabel: 'Something went wrong',
      autoClose: false,
      progress: 0.3,
      icon: false,
      theme: 'colored',
    });
  }

  return (
    <button
      className="bg-red-500 w-full font-bold text-white px-4 py-2 rounded"
      onClick={onSelect}>Remove</button>

  )
}
